//! Finite-domain UF SAT certificate (#finite-domain-uf-cert).
//!
//! The EPR finite-universe certificate declines whenever a function
//! application returns a binder sort, because the Herbrand universe is
//! then not generated by ground constants alone. Sledgehammer UF
//! problems (`uf.624244`) are exactly that shape, yet their candidate
//! models are finite: the EUF model's element universe per
//! uninterpreted sort is a finite set of congruence classes. This leg
//! makes that finiteness explicit and checks it:
//!
//! 1. FRAGMENT. The snapshot partitions into ground assertions and
//!    top-level foralls with quantifier-free bodies; every sort is
//!    plain uninterpreted or Bool; every application head is `=`/a
//!    Boolean connective or a declared UF symbol (authenticated by
//!    checked projection bindings, never by spelling alone).
//! 2. DOMAINS + SATURATION. Per sort, seed domains are the candidate
//!    model's values on the snapshot's ground subterms (one
//!    representative ground term per element) plus fresh spare
//!    elements. A domain-constrained EUF saturation solve (grounds +
//!    every seed-domain instance, with every depth-1 closure
//!    application decided equal to a representative by scoped
//!    backtracking) then exhibits a congruence-consistent finite
//!    structure; without it, candidate values plus modal completion
//!    are the fallback hint. Closure tables are read off that base
//!    model by evaluation, with functionality checked by value
//!    keying.
//! 3. INSTALL. Each symbol's closed table (rows for EVERY domain
//!    tuple, plus an explicit default) is installed into a cloned
//!    model via `install_model_check_total_uf`, so evaluation, the
//!    independent gate, and the printer all read the exact finite
//!    structure that step 4 verifies.
//! 4. VERIFY. Every ground assertion and every forall instance over
//!    the full domain cross-product must evaluate to definite
//!    `Bool(true)` under the installed model. The installed tables
//!    are total (rows + default), and the domains are the model's
//!    whole element universe for these sorts by construction of the
//!    closure, so the cross-product covers every binder point.
//!
//! Nothing is taken on trust: the candidate model only suggests the
//! domains and tables; a wrong suggestion fails step 2 or 4 and the
//! caller keeps its fail-closed `Unknown`. Grant-only: this leg can
//! never produce or influence an UNSAT verdict.

use super::*;
use ay_core::TheorySolver as _;

mod tables;
mod types;
use types::{FragmentScan, UfDomains};

/// Elements per sort in a certified domain.
const MAX_DOMAIN_PER_SORT: usize = 32;
/// Closure applications evaluated across all symbols.
const MAX_CLOSURE_APPS: usize = 8192;
/// Cross-product instances checked per forall.
const MAX_FORALL_TUPLES: usize = 4096;
/// UF symbols tabled by one certificate.
const MAX_TABLE_SYMBOLS: usize = 64;
/// Terms walked by the fragment scan.
const MAX_FRAGMENT_TERMS: usize = 200_000;
/// Closure applications decided by the saturation search.
const MAX_SATURATION_DECISIONS: usize = 256;
/// Search nodes (decision attempts) in the saturation search.
const MAX_SATURATION_NODES: usize = 32768;
/// Fresh spare elements added per sort before saturation.
const MAX_SPARE_ELEMENTS: usize = 2;

/// One UF symbol's signature as observed in the snapshot.
struct UfSignature {
    symbol: Symbol,
    arg_sorts: Vec<Sort>,
    result_sort: Sort,
}

impl Executor {
    /// Certify SAT by exhibiting the candidate model's finite element
    /// domains as an explicit total interpretation and verifying every
    /// snapshot assertion against it. See the module documentation.
    pub(in crate::executor) fn mbqi_sat_validated_finite_domain_uf(
        &mut self,
        snapshot: &[TermId],
        forall_quants: &[TermId],
    ) -> Option<CheckedMbqiSatAuthority> {
        let debug = ay_core::misc_cli_flags().debug_cert;
        let decline = |reason: &str| {
            if debug {
                tracing::debug!(target: "ay::cert::finite_domain_uf", "decline ({reason})");
            }
        };
        if forall_quants.is_empty() || self.external_stop_reason().is_some() {
            return None;
        }
        let mut candidate = self.last_model.clone()?;

        let (grounds, scan, checked_bindings) =
            self.uf_partition_and_scan(snapshot, forall_quants)?;

        // ---- Domains + closure tables. The candidate model seeds the
        // domains; a ground SATURATION solve over grounds + every
        // domain instance then exhibits a congruence-consistent finite
        // structure when the fragment is literal-shaped. Without it
        // (non-literal grounds, saturation UNSAT), the candidate's own
        // values plus modal completion are the fallback hint.
        let Some(mut seed_domains) = self.uf_domains(&mut candidate, &scan) else {
            decline("domain construction");
            return None;
        };
        // Spare elements: a genuine finite model may need values the
        // candidate collapsed or never materialized. Two fresh
        // representatives per sort (pinned in the candidate clone for
        // preference evaluation) widen every domain search space.
        for sort in &scan.sorts {
            let Sort::Uninterpreted(name) = sort else {
                continue;
            };
            for spare in 0..MAX_SPARE_ELEMENTS {
                let fresh = self
                    .ctx
                    .terms
                    .mk_fresh_var("ay_ufd_spare", Sort::Uninterpreted(name.clone()));
                let atom = format!("@ufd!{name}#{spare}");
                candidate
                    .completed_values
                    .insert(fresh, EvalValue::Element(atom.clone()));
                seed_domains.insert(sort.clone(), atom, fresh)?;
            }
        }
        let (base_model, domains) = match self.uf_saturation_model(
            &grounds,
            forall_quants,
            &seed_domains,
            &candidate,
            &scan,
        ) {
            Some((model, domains)) => (model, domains),
            None => (candidate.clone(), seed_domains),
        };
        let Some((domains, tables)) = self.uf_closure_tables(&base_model, &scan, &domains) else {
            decline("closure tables");
            return None;
        };

        let emitted = self.uf_install_and_verify(
            base_model,
            &scan,
            &domains,
            &tables,
            &grounds,
            forall_quants,
        )?;
        self.last_model = Some(emitted);
        if debug {
            tracing::debug!(target: "ay::cert::finite_domain_uf", "granted");
        }
        CheckedMbqiSatAuthority::for_current_with_projection_bindings(
            self,
            snapshot,
            checked_bindings,
        )
    }

    /// Snapshot coverage + fragment scan + declaration audit.
    fn uf_partition_and_scan(
        &self,
        snapshot: &[TermId],
        forall_quants: &[TermId],
    ) -> Option<(
        Vec<TermId>,
        FragmentScan,
        Option<ay_frontend::CheckedProjectionBindings>,
    )> {
        let debug = ay_core::misc_cli_flags().debug_cert;
        let decline = |reason: &str| {
            if debug {
                tracing::debug!(target: "ay::cert::finite_domain_uf", "decline ({reason})");
            }
        };
        // ---- Snapshot coverage, mirroring the EPR leg: every quantified
        // assertion must be a certified direct forall with QF body.
        let cert_set: HashSet<TermId> = forall_quants.iter().copied().collect();
        if forall_quants.iter().any(|q| !snapshot.contains(q)) {
            decline("certified forall outside snapshot");
            return None;
        }
        let partition = flatten_quantified_and_roots(&self.ctx.terms, snapshot);
        let mut grounds: Vec<TermId> = Vec::new();
        for &assertion in &partition {
            match self.ctx.terms.get(assertion) {
                TermData::Forall(_, body, _) => {
                    if !cert_set.contains(&assertion) || contains_quantifier(&self.ctx.terms, *body)
                    {
                        decline("uncertified or nested forall");
                        return None;
                    }
                }
                _ if contains_quantifier(&self.ctx.terms, assertion) => {
                    decline("non-top-level quantifier");
                    return None;
                }
                _ => grounds.push(assertion),
            }
        }

        // ---- Fragment scan: sorts, signatures, ground subterms.
        let mut scan = FragmentScan::default();
        for &root in snapshot {
            if !self.scan_uf_fragment(root, &mut scan) {
                decline("outside the finite-domain UF fragment");
                return None;
            }
        }
        if scan.signatures.len() > MAX_TABLE_SYMBOLS {
            decline("too many UF symbols");
            return None;
        }
        // Every binder sort is plain uninterpreted or Bool (checked in
        // the scan: binder sorts enter `sorts`).
        let requests: Vec<ay_frontend::ProjectionBindingRequest> = scan
            .signatures
            .values()
            .map(|sig| ay_frontend::ProjectionBindingRequest {
                symbol: sig.symbol.clone(),
                parameter_sorts: sig.arg_sorts.clone(),
                result_sort: sig.result_sort.clone(),
            })
            .collect();
        let checked_bindings = if requests.is_empty() {
            None
        } else {
            match self.ctx.check_projection_bindings(snapshot, &requests) {
                Ok(bindings) => Some(bindings),
                Err(_) => {
                    decline("declaration identity/signature audit");
                    return None;
                }
            }
        };

        Some((grounds, scan, checked_bindings))
    }

    /// Install the finite structure into `base_model` and verify every
    /// snapshot assertion against exactly it.
    fn uf_install_and_verify(
        &mut self,
        base_model: Model,
        scan: &FragmentScan,
        domains: &UfDomains,
        tables: &HashMap<String, Vec<(Vec<TermId>, TermId)>>,
        grounds: &[TermId],
        forall_quants: &[TermId],
    ) -> Option<Model> {
        let debug = ay_core::misc_cli_flags().debug_cert;
        let decline = |reason: &str| {
            if debug {
                tracing::debug!(target: "ay::cert::finite_domain_uf", "decline ({reason})");
            }
        };
        // ---- Install the finite structure and verify every snapshot
        // assertion against exactly it.
        let mut emitted = base_model;
        for (name, rows) in tables {
            let sig = &scan.signatures[name];
            let default = *domains.default_rep(&sig.result_sort)?;
            if self
                .install_model_check_total_uf(
                    &mut emitted,
                    name,
                    &sig.arg_sorts,
                    &sig.result_sort,
                    rows,
                    default,
                )
                .is_none()
            {
                decline("table install");
                return None;
            }
        }
        for &ground in grounds {
            if !matches!(self.evaluate_term(&emitted, ground), EvalValue::Bool(true)) {
                decline("ground assertion false under finite model");
                return None;
            }
        }
        for &q in forall_quants {
            if !self.uf_forall_holds_on_domains(&emitted, q, domains) {
                decline("forall false on a domain tuple");
                return None;
            }
        }

        // Pins preserve the checked ground projection for the public
        // validation funnel, as in the sibling certificates.
        let pins: Vec<(TermId, EvalValue)> = scan
            .ground_apps
            .iter()
            .map(|&term| (term, self.evaluate_term(&emitted, term)))
            .collect();
        if pins.iter().any(|(_, v)| matches!(v, EvalValue::Unknown)) {
            decline("indefinite ground application");
            return None;
        }
        if emitted
            .install_quantified_certificate_pins(&self.ctx.terms, pins)
            .is_none()
        {
            decline("certificate pins");
            return None;
        }
        Some(emitted)
    }

    /// Walk one snapshot root, admitting only the finite-domain UF
    /// fragment and recording signatures, sorts, ground subterms and
    /// ground UF applications. Bound-variable context decides which
    /// subterms are ground.
    fn scan_uf_fragment(&self, root: TermId, scan: &mut FragmentScan) -> bool {
        let mut stack: Vec<(TermId, HashSet<String>)> = vec![(root, HashSet::default())];
        while let Some((term, bound)) = stack.pop() {
            scan.work += 1;
            if scan.work > MAX_FRAGMENT_TERMS || self.external_stop_reason().is_some() {
                return false;
            }
            let sort = self.ctx.terms.sort(term).clone();
            if !self.uf_fragment_sort(&sort) {
                return false;
            }
            scan.sorts.insert(sort);
            // Groundness is per-subterm: a closed subterm under a binder
            // (a declared constant inside a forall body) is still ground.
            let ground = self.uf_term_avoids(term, &bound);
            match self.ctx.terms.get(term).clone() {
                TermData::App(symbol, args) => {
                    match &symbol {
                        Symbol::Named(name)
                            if matches!(name.as_str(), "=" | "and" | "or" | "=>" | "distinct") => {}
                        Symbol::Named(name) => {
                            let arg_sorts: Vec<Sort> = args
                                .iter()
                                .map(|&arg| self.ctx.terms.sort(arg).clone())
                                .collect();
                            let result_sort = self.ctx.terms.sort(term).clone();
                            match scan.signatures.get(name.as_str()) {
                                Some(sig)
                                    if sig.arg_sorts != arg_sorts
                                        || sig.result_sort != result_sort =>
                                {
                                    return false;
                                }
                                None => {
                                    scan.signatures.insert(
                                        name.to_string(),
                                        UfSignature {
                                            symbol: symbol.clone(),
                                            arg_sorts,
                                            result_sort,
                                        },
                                    );
                                }
                                _ => {}
                            }
                            if ground && !args.is_empty() {
                                scan.ground_apps.push(term);
                            }
                        }
                        _ => return false,
                    }
                    if ground {
                        scan.ground_subterms.push(term);
                    }
                    stack.extend(args.into_iter().map(|arg| (arg, bound.clone())));
                }
                TermData::Not(inner) => {
                    if ground {
                        scan.ground_subterms.push(term);
                    }
                    stack.push((inner, bound));
                }
                TermData::Ite(condition, then_branch, else_branch) => {
                    if ground {
                        scan.ground_subterms.push(term);
                    }
                    stack.push((else_branch, bound.clone()));
                    stack.push((then_branch, bound.clone()));
                    stack.push((condition, bound));
                }
                TermData::Forall(bindings, body, _) | TermData::Exists(bindings, body, _) => {
                    let mut inner = bound;
                    for (name, binder_sort) in &bindings {
                        if !self.uf_fragment_sort(binder_sort) {
                            return false;
                        }
                        scan.sorts.insert(binder_sort.clone());
                        inner.insert(name.clone());
                    }
                    stack.push((body, inner));
                }
                TermData::Var(name, _) => {
                    if !bound.contains(&name) {
                        scan.ground_subterms.push(term);
                    }
                }
                TermData::Const(Constant::Bool(_)) => {
                    scan.ground_subterms.push(term);
                }
                _ => return false,
            }
        }
        true
    }

    /// Whether `term` mentions none of the bound variable names.
    fn uf_term_avoids(&self, term: TermId, bound: &HashSet<String>) -> bool {
        if bound.is_empty() {
            return true;
        }
        let mut stack = vec![term];
        let mut seen: HashSet<TermId> = HashSet::default();
        while let Some(current) = stack.pop() {
            if !seen.insert(current) {
                continue;
            }
            match self.ctx.terms.get(current) {
                TermData::Var(name, _) => {
                    if bound.contains(name) {
                        return false;
                    }
                }
                TermData::App(_, args) => stack.extend(args.iter().copied()),
                TermData::Not(inner) => stack.push(*inner),
                TermData::Ite(c, t, e) => stack.extend([*c, *t, *e]),
                TermData::Forall(_, body, _) | TermData::Exists(_, body, _) => {
                    stack.push(*body);
                }
                TermData::Const(_) => {}
                _ => return false,
            }
        }
        true
    }

    /// Whether a sort belongs to the finite-domain UF fragment: Bool or
    /// a plain (non-parameterized, undeclared-packaged) uninterpreted
    /// sort.
    fn uf_fragment_sort(&self, sort: &Sort) -> bool {
        matches!(sort, Sort::Bool) || self.is_plain_uninterpreted_sort(sort)
    }
}

